import { readdirSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";

import { describe, expect, it } from "vitest";

import { answer, body } from "@/test/contract";

import type { RawRunDetail } from "./raw";

/**
 * raw.ts says which fields of the server's answers the app reads. This checks, on the real
 * recorded answers, that every one of those fields is there with that type: if the server renames
 * or retypes one (the contract files are regenerated by `scripts/app/gen_contract.py`, and a
 * pytest fails until they are), this fails and names it.
 */
type Kind = "string" | "number" | "boolean" | "object" | "array" | "string|null" | "object|null" | "number|null" | "any";

function check(value: unknown, spec: Record<string, Kind>, where: string): void {
  expect(typeof value, where).toBe("object");
  const obj = value as Record<string, unknown>;
  for (const [key, kind] of Object.entries(spec)) {
    expect(key in obj, `${where}.${key} is missing`).toBe(true);
    const v = obj[key];
    const actual = v === null ? "null" : Array.isArray(v) ? "array" : typeof v;
    expect(kind === "any" || kind.split("|").includes(actual), `${where}.${key} is ${actual}, expected ${kind}`).toBe(true);
  }
}

const MONEY: Record<string, Kind> = { amount: "string", currency: "string" };
const RUN: Record<string, Kind> = {
  run_id: "string", status: "string", org: "string|null", started_at: "string|null", started_by: "string|null",
  ended_at: "string|null", gates: "object", spend: "object", stop: "object|null", events: "number", head: "string", updated: "string|null",
};

describe("raw.ts against the real answers", () => {
  it("run list and summaries", () => {
    const list = body<{ runs: { spend: { total: unknown } }[]; truncated: boolean; scanned: number }>("demo", "runs");
    check(list, { runs: "array", truncated: "boolean", scanned: "number" }, "runs");
    for (const r of list.runs) {
      check(r, { ...RUN, tasks: "object" }, "runs[]");
      check(r.spend, { total: "object", calls: "number" }, "spend");
      check(r.spend.total, MONEY, "spend.total");
    }
  });

  it("run detail, tasks, gates, budgets and alerts (each of the recorded runs)", () => {
    for (const [file, name] of [["demo", "run_done"], ["demo", "run_needs_human"], ["windows", "run_alerts"], ["windows", "run_closed_window"], ["windows", "run_unrolled_window"], ["stop", "stopping_detail"]] as const) {
      const d = body<RawRunDetail>(file, name);
      check(d, { ...RUN, task_counts: "object", chief_of_staff: "string|null", canon_commit: "string|null", ledger: "object", tasks: "array", budgets: "array", budget_alerts: "array", approvals: "array" }, name);
      check(d.ledger, { stream: "string", seq: "number", head: "string", ok: "boolean" }, `${name}.ledger`);
      for (const t of d.tasks) {
        check(t, { id: "string", title: "string", assignee: "string|null", status: "string", attempt: "number", max_attempts: "number", attempts: "array", latest_gates: "array", spend: "object" }, `${name}.task`);
        check(t.spend, { total: "object", calls: "number" }, `${name}.task.spend`);
        for (const a of t.attempts) {
          for (const g of a.gates) check(g, { gate: "string", kind: "string", required: "boolean", outcome: "string", checked_by: "string", ledger_seq: "number", at: "string", verdicts: "array" }, `${name}.gate`);
        }
      }
      for (const b of d.budgets) check(b, { id: "string", scope: "string", scope_id: "string", limit: "object", spent: "object", reserved: "object", available: "object", blocked: "boolean", window: "string", on_breach: "string", window_start: "string|null" }, `${name}.budget`);
      for (const a of d.budget_alerts) {
        check(a, { kind: "string", ledger_seq: "number", budget: "string", scope: "string", held: "boolean", limit: "any" }, `${name}.alert`);
        if ("window_closed" in a) expect(a.window_closed, `${name}.alert.window_closed`).toBe(true);
      }
    }
  });

  it("ledger pages, events, verify and approvals", () => {
    const page = body<{ events: unknown[] }>("demo", "run_needs_human_ledger");
    check(page, { stream: "string", events: "array", head_seq: "number", head: "string", next_after_seq: "number", has_more: "boolean" }, "ledger page");
    for (const e of page.events) check(e, { stream: "string", seq: "number", type: "string", actor: "string", at: "string", run_id: "string|null", task_id: "string|null", payload: "object", cost: "object|null", cost_basis: "string|null", hash: "string", prev_hash: "string" }, "event");
    for (const [file, name] of [["demo", "verify_all"], ["tamper", "chain_verify_all"], ["tamper", "truncated_verify_all"], ["tamper", "unreadable_verify_all"], ["demo", "verify_run"]] as const) {
      const v = body<{ streams: unknown[] }>(file, name);
      check(v, { ok: "boolean", chain_ok: "boolean", verified: "boolean", streams: "array", anchors: "object" }, name);
      for (const s of v.streams) check(s, { stream: "string", ok: "boolean", checked: "number", problem: "string|null", at_seq: "number|null", anchors: "object|null" }, `${name}.stream`);
    }
    check(body("demo", "verify_stream"), { ok: "boolean", chain_ok: "boolean", verified: "boolean", stream: "string", checked: "number", problem: "string|null", anchors: "object", anchor_status: "object" }, "verify_stream");
    const problems = body<{ streams: { anchors: { problems: unknown[] } | null }[] }>("tamper", "truncated_verify_all").streams.flatMap((s) => s.anchors?.problems ?? []);
    expect(problems.length).toBeGreaterThan(0);
    for (const p of problems) check(p, { code: "string", detail: "string" }, "anchor problem");
    for (const a of body<unknown[]>("approvals", "list")) check(a, { id: "string", run_id: "string", task_id: "string|null", agent_id: "string", action: "object", asked_because: "string", status: "string", requested_at: "string", decided_by: "string|null", decided_at: "string|null", decision_reason_hash: "string|null", decision_reason: "string|null" }, "approval");
    check(body("approvals", "decided"), { ledger: "array", reason_available: "boolean" }, "approval view");
  });

  it("budgets, health and the stop answers", () => {
    for (const b of body<unknown[]>("windows", "budgets")) check(b, { id: "string", scope: "string", limit: "object", window: "string", on_breach: "string", window_start: "string|null", blocked: "boolean" }, "budget");
    check(body("windows", "budget_held"), { history: "array", history_truncated: "boolean" }, "budget detail");
    check(body("demo", "health"), { status: "string", org: "string|null", humans_enabled: "boolean" }, "health");
    check(body("stop", "no_reason"), { run_id: "string", status: "string", already_requested: "boolean", requested_by: "string", requested_at: "string", ledger_seq: "number" }, "stop");
  });

  it("the problem+json answers the app explains", () => {
    for (const [file, name, status, title] of [
      ["stop", "forbidden", 403, "authentication_required"],
      ["stop", "no_content_store", 503, "content_store_unavailable"],
      ["demo", "stop_finished", 409, "run_finished"],
      ["demo", "run_missing", 404, "not_found"],
      ["approvals", "decide_again", 409, "approval_refused"],
      ["approvals", "decide_no_content_store", 503, "content_store_unavailable"],
    ] as const) {
      const a = answer<{ title: string; detail: string; status: number }>(file, name);
      expect(a.status, name).toBe(status);
      check(a.body, { title: "string", detail: "string", status: "number" }, name);
      expect(a.body.title, name).toBe(title);
    }
  });
});

/** Every non-test source file of the API layer: the guard below reads all of them. */
function apiSources(dir: string): { file: string; text: string }[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const full = join(dir, e.name);
    if (e.isDirectory()) return apiSources(full);
    return /\.tsx?$/.test(e.name) && !/\.test\.tsx?$/.test(e.name) ? [{ file: full, text: readFileSync(full, "utf8") }] : [];
  });
}

/** The text of the first argument of the call whose `(` is at `open`: up to the first top-level comma or `)`. */
function firstArgument(text: string, open: number): string {
  let depth = 0;
  let quote = "";
  const braces: number[] = [];
  for (let i = open + 1; i < text.length; i++) {
    const c = text.charAt(i);
    if (quote !== "") {
      if (c === "\\") i++;
      else if (quote === "`" && c === "$" && text.charAt(i + 1) === "{") {
        braces.push(depth);
        depth++;
        i++;
        quote = "";
      } else if (c === quote) quote = "";
      continue;
    }
    if (c === '"' || c === "'" || c === "`") quote = c;
    else if (c === "(" || c === "[" || c === "{") depth++;
    else if (c === ")" || c === "]" || c === "}") {
      if (depth === 0) return text.slice(open + 1, i).trim();
      depth--;
      if (c === "}" && braces.length > 0 && braces[braces.length - 1] === depth) {
        braces.pop();
        quote = "`";
      }
    } else if (c === "," && depth === 0) return text.slice(open + 1, i).trim();
  }
  return text.slice(open + 1).trim();
}

interface Found {
  file: string;
  method: string;
  expression: string;
  path: string | null;
}

/** Every `http.<method>(path, ...)` in the API layer, the path resolved through the file's `const x = "/v1/..."` strings. */
function findCalls(): Found[] {
  const found: Found[] = [];
  for (const { file, text } of apiSources(resolve(process.cwd(), "src/api"))) {
    const defs = [...text.matchAll(/\bconst (\w+) = ([`"])(\/v1\/[^`"]*)\2/g)].map((m) => ({ at: m.index, name: m[1] ?? "", value: m[3] ?? "" }));
    // The nearest definition above the call wins: `path` is a different string in the stop and the budget calls.
    let consts = new Map<string, string>();
    const constsAt = (at: number) => new Map(defs.filter((d) => d.at < at).map((d) => [d.name, d.value] as const));
    // `${name}` is a known constant, `${expr}` one path segment, and a `${...}` that holds a template of its own is an optional query suffix.
    const resolveText = (literal: string): string => {
      let out = "";
      for (let i = 0; i < literal.length; i++) {
        if (literal.charAt(i) === "$" && literal.charAt(i + 1) === "{") {
          let depth = 1;
          let j = i + 2;
          while (j < literal.length && depth > 0) {
            if (literal.charAt(j) === "{") depth++;
            else if (literal.charAt(j) === "}") depth--;
            j++;
          }
          const inner = literal.slice(i + 2, j - 1);
          out += inner.includes("`") ? "" : (consts.has(inner) ? resolveText(consts.get(inner) ?? "") : "{}");
          i = j - 1;
        } else out += literal.charAt(i);
      }
      return out.replace(/\?.*$/, "");
    };
    // `write(path, ...)` is models.ts's own helper for `http.post`.
    for (const m of text.matchAll(/\b(?:http\.(get|post|put|delete)(?:<[^()]*>)?|(write))\(/g)) {
      consts = constsAt(m.index);
      if (m[2] !== undefined && !file.endsWith("models.ts")) continue;
      const expression = firstArgument(text, m.index + m[0].length - 1);
      const quoted = /^([`"])([\s\S]*)\1$/.exec(expression);
      const named = /^\w+$/.test(expression) ? consts.get(expression) : undefined;
      const literal = quoted === null ? named : quoted[2];
      // `${x === "a" ? "a" : "b"}` (a segment that is one of two words) is both routes.
      const either = literal === undefined ? null : /\$\{[^}`]*\? "(\w+)" : "(\w+)"\}/.exec(literal);
      const variants = literal === undefined ? [] : either === null ? [literal] : [literal.replace(either[0], either[1] ?? ""), literal.replace(either[0], either[2] ?? "")];
      for (const variant of variants) {
        const path = resolveText(variant);
        found.push({ file, method: (m[1] ?? "post").toUpperCase(), expression, path: path.startsWith("/v1/") ? path : null });
      }
      if (literal === undefined) found.push({ file, method: (m[1] ?? "post").toUpperCase(), expression, path: null });
    }
  }
  return found;
}

/**
 * A call this test cannot read the path of (a helper builds it). Each one is a GET, PUT or DELETE
 * on a route that is not deprecated; a new one must be added here on purpose.
 */
const BUILT_BY_A_HELPER = new Set(["keyPath(t)", "keyPath(i)", "path", "dashboardPath(\"verification\", w)", "dashboardPath(\"verifiers\", w)", "dashboardPath(\"cost-latency\", w)", "dashboardPath(\"approvals\", w)"]);

/** Deprecated routes the app still calls, each with the issue and the reason (none: every one has a replacement). */
const STILL_CALLED: Record<string, string> = {};

describe("the routes the API layer calls (W3)", () => {
  const recorded = body<Record<string, string[]>>("demo", "openapi");
  const deprecated = body<string[]>("demo", "openapi_deprecated");
  const all = findCalls();
  const calls = all.filter((c) => c.path !== null);
  const template = (path: string) => Object.keys(recorded).find((t) => new RegExp(`^${t.replace(/\{[^}]*\}/g, "[^/]+")}$`).test(path.replace(/\{\}/g, "x")));

  it("reads every client file, models.ts and the budget and stop calls included", () => {
    expect(calls.length).toBeGreaterThan(45);
    const seen = new Set(calls.map((c) => `${c.method} ${c.path ?? ""}`));
    expect(seen).toContain("POST /v1/models/catalog/entries/approve");
    expect(seen).toContain("POST /v1/budgets/{}/unblock");
    expect(seen).toContain("POST /v1/runs/{}/stop");
    expect(all.filter((c) => c.path === null).map((c) => c.expression).filter((e) => !BUILT_BY_A_HELPER.has(e))).toEqual([]);
  });

  it("every path and method the client calls is served and none is marked deprecated", () => {
    for (const { method, path } of calls) {
      const t = template(path ?? "");
      expect(t, `${method} ${path ?? ""} is not in the server's OpenAPI`).toBeDefined();
      expect(recorded[t ?? ""], `${method} ${path ?? ""}`).toContain(method);
      const route = `${method} ${t ?? ""}`;
      if (deprecated.includes(route)) {
        expect(STILL_CALLED[route], `${route} is deprecated on the server and the app calls it (move it, or allow it with a reason and #889)`).toBeDefined();
      }
    }
  });

  it("the allowlist holds nothing that is no longer called or no longer deprecated", () => {
    for (const route of Object.keys(STILL_CALLED)) {
      expect(deprecated).toContain(route);
      expect(calls.map((c) => `${c.method} ${template(c.path ?? "") ?? ""}`)).toContain(route);
    }
  });

  it("the recorded list does name the routes the app moved off", () => {
    expect(deprecated).toContain("POST /v1/approvals/{approval_id}/decision");
    expect(deprecated).toContain("GET /v1/org/halt");
    expect(deprecated).toContain("POST /v1/models/catalog/approve");
    expect(recorded["/v1/org/status"]).toContain("GET");
  });
});
